from collections import defaultdict, deque
import collections, sys
sys.setrecursionlimit(10000)
s=pd.read_csv('data/songs.csv'); m=pd.read_csv('data/samples.csv')
for tr,root in [('king_2',64739),('hit',233667),('funky_3',234409)]:
    e=m[m.tree==tr]
    ch=defaultdict(set)
    for a,b in zip(e.start_node_id,e.end_node_id): ch[b].add(a)
    # memo longest path from root
    from functools import lru_cache
    @lru_cache(None)
    def L(u):
        if not ch[u]: return 0
        return 1+max(L(v) for v in ch[u])
    # shortest BFS
    dist={root:0}; q=deque([root])
    while q:
        u=q.popleft()
        for v in ch[u]:
            if v not in dist: dist[v]=dist[u]+1; q.append(v)
    print(tr,'shortest max',max(dist.values()),'longest max',L(root),'nodes',len(set(e.start_node_id)|set(e.end_node_id)))
    # compute longest depth for each node by memo from root? L(u) is max remaining to leaf, not depth.
    # For longest path from root to each node, use DP topo:
    # Kahn: start with root, remove edges, track max dist.
    indeg=defaultdict(int)
    nodes=set(e.start_node_id)|set(e.end_node_id)
    for n in nodes: indeg[n]=0
    for a,b in zip(e.start_node_id,e.end_node_id): indeg[a]+=1  # a has parent b (incoming edge from parent to child)
    q=deque([n for n in nodes if indeg[n]==0]); order=[]
    while q:
        u=q.popleft(); order.append(u)
        for v in ch[u]:
            indeg[v]-=1
            if indeg[v]==0: q.append(v)
    dp={n:-10**9 for n in nodes}; dp[root]=0
    for u in order:
        for v in ch[u]: dp[v]=max(dp[v],dp[u]+1)
    vals=[v for v in dp.values() if v>=0]
    print('longest depth dist',collections.Counter(vals), 'max',max(vals))
